    @verbatim
        <script>
            const collectionData =
                "opencollection: 1.0.0\ninfo:\n  name: Verita-API\n  version: 1.0.0\nconfig:\n  proxy:\n    inherit: true\n    config:\n      protocol: http\n      hostname: ''\n      port: ''\n      auth:\n        username: ''\n        password: ''\n      bypassProxy: ''\n  environments:\n    - name: Local\n      variables:\n        - name: baseUri\n          value: http://localhost:8000/api/v1\n          description: Verita REST API base endpoint\n        - name: apiOrigin\n          value: http://localhost:8000\n          description: API origin for Laravel broadcasting and storage downloads\n        - name: wsHost\n          value: localhost\n          description: Laravel Reverb WebSocket server host\n        - name: wsPort\n          value: '8080'\n          description: Laravel Reverb WebSocket port\n        - name: reverbAppKey\n          value: eafnuy9gwxipsopxuepc\n          description: Laravel Reverb application key\n        - name: idempotencyKey\n          value: ''\n          description: UUID v4 idempotency token for safe submission retries\n        - name: caseId\n          value: ''\n          description: Dynamic UUID of current active case under test\n        - name: trackingPin\n          value: ''\n          description: Dynamic 6-character cryptographic tracking PIN for Case Reporter\n        - name: staffEmail\n          secret: true\n          description: Fallback staff email\n        - name: staffPassword\n          secret: true\n          description: Fallback staff password\n        - name: staffToken\n          secret: true\n          description: Active staff bearer JWT token (synced on login)\n        - name: caseToken\n          secret: true\n          description: Anonymous Case Reporter bearer JWT token (from verify-pin)\n        - name: managerEmail\n          secret: true\n          description: Testing account - Manager email\n        - name: managerPassword\n          secret: true\n          description: Testing account - Manager password\n        - name: managerToken\n          secret: true\n          description: Persisted Bearer JWT token for Manager\n        - name: deptHeadEmail\n          secret: true\n          description: Testing account - Department Head email\n        - name: deptHeadPassword\n          secret: true\n          description: Testing account - Department Head password\n        - name: deptHeadToken\n          secret: true\n          description: Persisted Bearer JWT token for Department Head\n        - name: departmentHeadId\n          value: ''\n          description: Department head user UUID captured dynamically\n        - name: departmentId\n          value: ''\n          description: Department UUID captured dynamically\n        - name: notificationId\n          value: ''\n          description: Notification ID captured dynamically\n        - name: evidenceId\n          value: ''\n          description: Evidence file ID captured dynamically\n        - name: socketId\n          value: '12345.6789'\n          description: Socket ID used for Pusher channel authorization\n        - name: broadcastAuthSignature\n          value: ''\n          description: Pusher signature returned from /broadcasting/auth\nitems:\n  - info:\n      name: Health\n      type: folder\n      seq: 1\n    request:\n      auth: inherit\n    items:\n      - info:\n          name: Ping API\n          type: http\n          seq: 1\n        http:\n          method: GET\n          url: '{{ baseUri }}/ping'\n          headers:\n            - name: Accept\n              value: application/json\n        runtime:\n          scripts:\n            - type: tests\n              code: |-\n                test(\"Status is 200 OK\", function() {\n                  expect(res.status).to.equal(200);\n                });\n                test(\"Response returns pong message\", function() {\n                  expect(res.body).to.be.an('object');\n                  if (res.body.message) {\n                    expect(res.body.message).to.equal('pong');\n                  }\n                });\n          assertions:\n            - expression: res.status\n              operator: eq\n              value: '200'\n        settings:\n          encodeUrl: true\n          timeout: 0\n          followRedirects: true\n          maxRedirects: 5\n          forwardAuthorizationHeader: true\n  - info:\n      name: Account & Notifications\n      type: folder\n      seq: 2\n    request:\n      auth: inherit\n    items:\n      - info:\n          name: Get Staff Dashboard\n          type: http\n          seq: 1\n        http:\n          method: GET\n          url: '{{ baseUri }}/account/dashboard'\n          headers:\n            - name: Accept\n              value: application/json\n          auth:\n            type: bearer\n            token: '{{ staffToken }}'\n        runtime:\n          scripts:\n            - type: tests\n              code: |-\n                test(\"Status is 200 OK\", function() {\n                  expect(res.status).to.equal(200);\n                });\n                test(\"Returns staff account overview\", function() {\n                  expect(res.body).to.be.an('object');\n                });\n          assertions:\n            - expression: res.status\n              operator: eq\n              value: '200'\n        settings:\n          encodeUrl: true\n          timeout: 0\n          followRedirects: true\n          maxRedirects: 5\n          forwardAuthorizationHeader: true\n      - info:\n          name: Update Profile\n          type: http\n          seq: 2\n        http:\n          method: PUT\n          url: '{{ baseUri }}/account/profile'\n          headers:\n            - name: Content-Type\n              value: application/json\n            - name: Accept\n              value: application/json\n          body:\n            type: json\n            data: |-\n              {\n                \"name\": \"Carmine Akanabe\",\n                \"current_password\": \"password\"\n              }\n          auth:\n            type: bearer\n            token: '{{ staffToken }}'\n        runtime:\n          scripts:\n            - type: tests\n              code: |-\n                test(\"Status is 200 OK\", function() {\n                  expect(res.status).to.equal(200);\n                });\n                test(\"Returns updated user resource\", function() {\n                  expect(res.body).to.be.an('object');\n                  if (res.body.data && res.body.data.name) {\n                    expect(res.body.data.name).to.equal('Carmine Akanabe');\n                  }\n                });\n          assertions:\n            - expression: res.status\n              operator: eq\n              value: '200'\n        settings:\n          encodeUrl: true\n          timeout: 0\n          followRedirects: true\n          maxRedirects: 5\n          forwardAuthorizationHeader: true\n      - info:\n          name: Get Notifications\n          type: http\n          seq: 3\n        http:\n          method: GET\n          url: '{{ baseUri }}/notifications'\n          headers:\n            - name: Accept\n              value: application/json\n          auth:\n            type: bearer\n            token: '{{ staffToken }}'\n        runtime:\n          scripts:\n            - type: after-response\n              code: |-\n                if (res.status === 200 && res.body.data && res.body.data.length > 0) {\n                  bru.setVar(\"notificationId\", res.body.data[0].id);\n                }\n            - type: tests\n              code: |-\n                test(\"Status is 200 OK\", function() {\n                  expect(res.status).to.equal(200);\n                });\n                test(\"Returns notification collection\", function() {\n                  expect(res.body.data).to.be.an('array');\n                });\n          assertions:\n            - expression: res.status\n              operator: eq\n              value: '200'\n        settings:\n          encodeUrl: true\n          timeout: 0\n          followRedirects: true\n          maxRedirects: 5\n          forwardAuthorizationHeader: true\n      - info:\n          name: Mark Notification Read\n          type: http\n          seq: 4\n        http:\n          method: PATCH\n          url: '{{ baseUri }}/notifications/{{ notificationId }}'\n          headers:\n            - name: Accept\n              value: application/json\n          auth:\n            type: bearer\n            token: '{{ staffToken }}'\n        runtime:\n          scripts:\n            - type: tests\n              code: |-\n                test(\"Status is 204 No Content\", function() {\n                  expect(res.status).to.equal(204);\n                });\n          assertions:\n            - expression: res.status\n              operator: eq\n              value: '204'\n        settings:\n          encodeUrl: true\n          timeout: 0\n          followRedirects: true\n          maxRedirects: 5\n          forwardAuthorizationHeader: true\n      - info:\n          name: Logout\n          type: http\n          seq: 5\n        http:\n          method: POST\n          url: '{{ baseUri }}/auth/logout'\n          headers:\n            - name: Accept\n              value: application/json\n          auth:\n            type: bearer\n            token: '{{ staffToken }}'\n        runtime:\n          scripts:\n            - type: tests\n              code: |-\n                test(\"Status is 204 No Content\", function() {\n                  expect(res.status).to.equal(204);\n                });\n          assertions:\n            - expression: res.status\n              operator: eq\n              value: '204'\n        settings:\n          encodeUrl: true\n          timeout: 0\n          followRedirects: true\n          maxRedirects: 5\n          forwardAuthorizationHeader: true\n  - info:\n      name: Manager\n      type: folder\n      seq: 3\n    request:\n      auth: inherit\n    items:\n      - info:\n          name: Manager Login\n          type: http\n          seq: 1\n        http:\n          method: POST\n          url: '{{ baseUri }}/auth/login'\n          headers:\n            - name: Content-Type\n              value: application/json\n            - name: Accept\n              value: application/json\n          body:\n            type: json\n            data: |-\n              {\n                \"email\": \"{{ managerEmail }}\",\n                \"password\": \"{{ managerPassword }}\"\n              }\n        runtime:\n          scripts:\n            - type: after-response\n              code: |-\n                if (res.status === 200 && res.body.token) {\n                  bru.setVar(\"managerToken\", res.body.token);\n                  bru.setVar(\"staffToken\", res.body.token);\n                }\n            - type: tests\n              code: |-\n                test(\"Status is 200 OK\", function() {\n                  expect(res.status).to.equal(200);\n                });\n                test(\"JWT token returned\", function() {\n                  expect(res.body.token).to.be.a('string');\n                });\n                test(\"User role is MANAGER\", function() {\n                  expect(res.body.user.role).to.equal('MANAGER');\n                });\n          assertions:\n            - expression: res.status\n              operator: eq\n              value: '200'\n        settings:\n          encodeUrl: true\n          timeout: 0\n          followRedirects: true\n          maxRedirects: 5\n          forwardAuthorizationHeader: true\n      - info:\n          name: Get Departments\n          type: http\n          seq: 2\n        http:\n          method: GET\n          url: '{{ baseUri }}/departments'\n          headers:\n            - name: Accept\n              value: application/json\n          auth:\n            type: bearer\n            token: '{{ managerToken }}'\n        runtime:\n          scripts:\n            - type: after-response\n              code: |-\n                if (res.status === 200 && res.body.data && res.body.data.length > 0) {\n                  bru.setVar(\"departmentId\", res.body.data[0].id);\n                }\n            - type: tests\n              code: |-\n                test(\"Status is 200 OK\", function() {\n                  expect(res.status).to.equal(200);\n                });\n                test(\"Returns array of departments\", function() {\n                  expect(res.body.data).to.be.an('array');\n                });\n          assertions:\n            - expression: res.status\n              operator: eq\n              value: '200'\n        settings:\n          encodeUrl: true\n          timeout: 0\n          followRedirects: true\n          maxRedirects: 5\n          forwardAuthorizationHeader: true\n      - info:\n          name: Create Department\n          type: http\n          seq: 3\n        http:\n          method: POST\n          url: '{{ baseUri }}/departments'\n          headers:\n            - name: Content-Type\n              value: application/json\n            - name: Accept\n              value: application/json\n          body:\n            type: json\n            data: |-\n              {\n                \"name\": \"Audit & Compliance Division\",\n                \"code\": \"ACD\",\n                \"description\": \"Internal controls and investigative compliance oversight.\"\n              }\n          auth:\n            type: bearer\n            token: '{{ managerToken }}'\n        runtime:\n          scripts:\n            - type: after-response\n              code: |-\n                if (res.status === 201 && res.body.data) {\n                  bru.setVar(\"departmentId\", res.body.data.id);\n                }\n            - type: tests\n              code: |-\n                test(\"Status is 201 Created\", function() {\n                  expect(res.status).to.equal(201);\n                });\n                test(\"Created department has required attributes\", function() {\n                  expect(res.body.data.id).to.be.a('string');\n                  expect(res.body.data.name).to.equal('Audit & Compliance Division');\n                  expect(res.body.data.code).to.equal('ACD');\n                });\n          assertions:\n            - expression: res.status\n              operator: eq\n              value: '201'\n        settings:\n          encodeUrl: true\n          timeout: 0\n          followRedirects: true\n          maxRedirects: 5\n          forwardAuthorizationHeader: true\n      - info:\n          name: Update Department\n          type: http\n          seq: 4\n        http:\n          method: PUT\n          url: '{{ baseUri }}/departments/{{ departmentId }}'\n          headers:\n            - name: Content-Type\n              value: application/json\n            - name: Accept\n              value: application/json\n          body:\n            type: json\n            data: |-\n              {\n                \"name\": \"Ethics & Regulatory Compliance\",\n                \"code\": \"ERC\",\n                \"description\": \"Organizational integrity and compliance verification.\"\n              }\n          auth:\n            type: bearer\n            token: '{{ managerToken }}'\n        runtime:\n          scripts:\n            - type: tests\n              code: |-\n                test(\"Status is 200 OK\", function() {\n                  expect(res.status).to.equal(200);\n                });\n                test(\"Department details are updated\", function() {\n                  expect(res.body.data.name).to.equal('Ethics & Regulatory Compliance');\n                  expect(res.body.data.code).to.equal('ERC');\n                });\n          assertions:\n            - expression: res.status\n              operator: eq\n              value: '200'\n        settings:\n          encodeUrl: true\n          timeout: 0\n          followRedirects: true\n          maxRedirects: 5\n          forwardAuthorizationHeader: true\n      - info:\n          name: Get Department Heads\n          type: http\n          seq: 5\n        http:\n          method: GET\n          url: '{{ baseUri }}/department-heads'\n          headers:\n            - name: Accept\n              value: application/json\n          auth:\n            type: bearer\n            token: '{{ managerToken }}'\n        runtime:\n          scripts:\n            - type: after-response\n              code: |-\n                if (res.status === 200 && res.body.data && res.body.data.length > 0) {\n                  bru.setVar(\"departmentHeadId\", res.body.data[0].id);\n                }\n            - type: tests\n              code: |-\n                test(\"Status is 200 OK\", function() {\n                  expect(res.status).to.equal(200);\n                });\n                test(\"Returns array of department heads\", function() {\n                  expect(res.body.data).to.be.an('array');\n                });\n          assertions:\n            - expression: res.status\n              operator: eq\n              value: '200'\n        settings:\n          encodeUrl: true\n          timeout: 0\n          followRedirects: true\n          maxRedirects: 5\n          forwardAuthorizationHeader: true\n      - info:\n          name: Create Department Head\n          type: http\n          seq: 6\n        http:\n          method: POST\n          url: '{{ baseUri }}/department-heads'\n          headers:\n            - name: Content-Type\n              value: application/json\n            - name: Accept\n              value: application/json\n          body:\n            type: json\n            data: |-\n              {\n                \"name\": \"Dr. Sarah Vance\",\n                \"email\": \"sarah.vance@verita-system.org\",\n                \"department_id\": \"{{ departmentId }}\",\n                \"password\": \"password\"\n              }\n          auth:\n            type: bearer\n            token: '{{ managerToken }}'\n        runtime:\n          scripts:\n            - type: after-response\n              code: |-\n                if (res.status === 201 && res.body.data) {\n                  bru.setVar(\"departmentHeadId\", res.body.data.id);\n                }\n            - type: tests\n              code: |-\n                test(\"Status is 201 Created\", function() {\n                  expect(res.status).to.equal(201);\n                });\n                test(\"Created department head has valid role\", function() {\n                  expect(res.body.data.role).to.equal('DEPARTMENT_HEAD');\n                  expect(res.body.data.email).to.equal('sarah.vance@verita-system.org');\n                });\n          assertions:\n            - expression: res.status\n              operator: eq\n              value: '201'\n        settings:\n          encodeUrl: true\n          timeout: 0\n          followRedirects: true\n          maxRedirects: 5\n          forwardAuthorizationHeader: true\n      - info:\n          name: Update Department Head\n          type: http\n          seq: 7\n        http:\n          method: PATCH\n          url: '{{ baseUri }}/department-heads/{{ departmentHeadId }}'\n          headers:\n            - name: Content-Type\n              value: application/json\n            - name: Accept\n              value: application/json\n          body:\n            type: json\n            data: |-\n              {\n                \"name\": \"Dr. Sarah Vance-Holt\",\n                \"department_id\": \"{{ departmentId }}\"\n              }\n          auth:\n            type: bearer\n            token: '{{ managerToken }}'\n        runtime:\n          scripts:\n            - type: tests\n              code: |-\n                test(\"Status is 200 OK\", function() {\n                  expect(res.status).to.equal(200);\n                });\n                test(\"Department head name is updated\", function() {\n                  expect(res.body.data.name).to.equal('Dr. Sarah Vance-Holt');\n                });\n          assertions:\n            - expression: res.status\n              operator: eq\n              value: '200'\n        settings:\n          encodeUrl: true\n          timeout: 0\n          followRedirects: true\n          maxRedirects: 5\n          forwardAuthorizationHeader: true\n      - info:\n          name: Get Case Assignments\n          type: http\n          seq: 8\n        http:\n          method: GET\n          url: '{{ baseUri }}/case-assignments'\n          headers:\n            - name: Accept\n              value: application/json\n          auth:\n            type: bearer\n            token: '{{ managerToken }}'\n        runtime:\n          scripts:\n            - type: tests\n              code: |-\n                test(\"Status is 200 OK\", function() {\n                  expect(res.status).to.equal(200);\n                });\n                test(\"Returns list of unassigned or escalated cases\", function() {\n                  expect(res.body.data).to.be.an('array');\n                });\n          assertions:\n            - expression: res.status\n              operator: eq\n              value: '200'\n        settings:\n          encodeUrl: true\n          timeout: 0\n          followRedirects: true\n          maxRedirects: 5\n          forwardAuthorizationHeader: true\n      - info:\n          name: Assign Case\n          type: http\n          seq: 9\n        http:\n          method: POST\n          url: '{{ baseUri }}/case-assignments/{{ caseId }}'\n          headers:\n            - name: Content-Type\n              value: application/json\n            - name: Accept\n              value: application/json\n          body:\n            type: json\n            data: |-\n              {\n                \"department_head_id\": \"{{ departmentHeadId }}\",\n                \"reason\": \"Direct management reassignment to departmental lead investigator.\"\n              }\n          auth:\n            type: bearer\n            token: '{{ managerToken }}'\n        runtime:\n          scripts:\n            - type: tests\n              code: |-\n                test(\"Status is 200 OK\", function() {\n                  expect(res.status).to.equal(200);\n                });\n                test(\"Case assigned investigator matches specified ID\", function() {\n                  expect(res.body.data.id).to.equal(bru.getVar('caseId'));\n                });\n          assertions:\n            - expression: res.status\n              operator: eq\n              value: '200'\n        settings:\n          encodeUrl: true\n          timeout: 0\n          followRedirects: true\n          maxRedirects: 5\n          forwardAuthorizationHeader: true\n      - info:\n          name: Get Reports\n          type: http\n          seq: 10\n        http:\n          method: GET\n          url: '{{ baseUri }}/reports/user-engagement'\n          headers:\n            - name: Accept\n              value: application/json\n          auth:\n            type: bearer\n            token: '{{ managerToken }}'\n        runtime:\n          scripts:\n            - type: tests\n              code: |-\n                test(\"Status is 200 OK\", function() {\n                  expect(res.status).to.equal(200);\n                });\n                test(\"Returns analytics report payload\", function() {\n                  expect(res.body.data).to.be.an('object');\n                });\n          assertions:\n            - expression: res.status\n              operator: eq\n              value: '200'\n        settings:\n          encodeUrl: true\n          timeout: 0\n          followRedirects: true\n          maxRedirects: 5\n          forwardAuthorizationHeader: true\n      - info:\n          name: Get All Audit Logs\n          type: http\n          seq: 11\n        http:\n          method: GET\n          url: '{{ baseUri }}/audit-logs'\n          headers:\n            - name: Accept\n              value: application/json\n          auth:\n            type: bearer\n            token: '{{ managerToken }}'\n        runtime:\n          scripts:\n            - type: tests\n              code: |-\n                test(\"Status is 200 OK\", function() {\n                  expect(res.status).to.equal(200);\n                });\n                test(\"Returns system-wide immutable audit ledger\", function() {\n                  expect(res.body.data).to.be.an('array');\n                });\n          assertions:\n            - expression: res.status\n              operator: eq\n              value: '200'\n        settings:\n          encodeUrl: true\n          timeout: 0\n          followRedirects: true\n          maxRedirects: 5\n          forwardAuthorizationHeader: true\n      - info:\n          name: Delete Department Head\n          type: http\n          seq: 12\n        http:\n          method: DELETE\n          url: '{{ baseUri }}/department-heads/{{ departmentHeadId }}'\n          headers:\n            - name: Accept\n              value: application/json\n          auth:\n            type: bearer\n            token: '{{ managerToken }}'\n        runtime:\n          scripts:\n            - type: tests\n              code: |-\n                test(\"Status is 204 No Content\", function() {\n                  expect(res.status).to.equal(204);\n                });\n          assertions:\n            - expression: res.status\n              operator: eq\n              value: '204'\n        settings:\n          encodeUrl: true\n          timeout: 0\n          followRedirects: true\n          maxRedirects: 5\n          forwardAuthorizationHeader: true\n      - info:\n          name: Delete Department\n          type: http\n          seq: 13\n        http:\n          method: DELETE\n          url: '{{ baseUri }}/departments/{{ departmentId }}'\n          headers:\n            - name: Accept\n              value: application/json\n          auth:\n            type: bearer\n            token: '{{ managerToken }}'\n        runtime:\n          scripts:\n            - type: tests\n              code: |-\n                test(\"Status is 204 No Content\", function() {\n                  expect(res.status).to.equal(204);\n                });\n          assertions:\n            - expression: res.status\n              operator: eq\n              value: '204'\n        settings:\n          encodeUrl: true\n          timeout: 0\n          followRedirects: true\n          maxRedirects: 5\n          forwardAuthorizationHeader: true\n  - info:\n      name: Reporter\n      type: folder\n      seq: 4\n    request:\n      auth: inherit\n    items:\n      - info:\n          name: Submit Case\n          type: http\n          seq: 1\n        http:\n          method: POST\n          url: '{{ baseUri }}/cases'\n          headers:\n            - name: Accept\n              value: application/json\n            - name: Idempotency-Key\n              value: '{{ idempotencyKey }}'\n          body:\n            type: multipart-form\n            data:\n              - name: departmentId\n                type: text\n                value: '{{ departmentId }}'\n              - name: description\n                type: text\n                value: Financial irregularities identified in departmental equipment procurement.\n              - name: purposeOfTransaction\n                type: text\n                value: IT server hardware procurement\n              - name: amountInvolved\n                type: text\n                value: '8500'\n              - name: personInvolved\n                type: text\n                value: Marcus Sterling\n              - name: transactionDate\n                type: text\n                value: '2026-09-15'\n              - name: concernsDepartmentHead\n                type: text\n                value: 'false'\n        runtime:\n          scripts:\n            - type: before-request\n              code: |-\n                function generateUUID() {\n                  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {\n                    const r = Math.random() * 16 | 0;\n                    const v = c === 'x' ? r : (r & 0x3 | 0x8);\n                    return v.toString(16);\n                  });\n                }\n                if (!bru.getVar('idempotencyKey')) {\n                  bru.setVar('idempotencyKey', generateUUID());\n                }\n            - type: after-response\n              code: |-\n                if (res.status === 201 && res.body.data) {\n                  bru.setVar(\"caseId\", res.body.data.caseId);\n                  bru.setVar(\"trackingPin\", res.body.data.trackingPin);\n                }\n            - type: tests\n              code: |-\n                test(\"Status is 201 Created\", function() {\n                  expect(res.status).to.equal(201);\n                });\n                test(\"Returns generated caseId and 6-char tracking PIN\", function() {\n                  expect(res.body.data.caseId).to.be.a('string');\n                  expect(res.body.data.trackingPin).to.be.a('string');\n                  expect(res.body.data.trackingPin.length).to.equal(6);\n                  expect(res.body.data.status).to.equal('SUBMITTED');\n                });\n          assertions:\n            - expression: res.status\n              operator: eq\n              value: '201'\n        settings:\n          encodeUrl: true\n          timeout: 0\n          followRedirects: true\n          maxRedirects: 5\n          forwardAuthorizationHeader: true\n      - info:\n          name: Verify PIN\n          type: http\n          seq: 2\n        http:\n          method: POST\n          url: '{{ baseUri }}/cases/{{ caseId }}/verify-pin'\n          headers:\n            - name: Content-Type\n              value: application/json\n            - name: Accept\n  