{\n                  expect(res.body.data.caseId).to.equal(bru.getVar('caseId'));\n                  expect(res.body.data.status).to.be.a('string');\n                });\n          assertions:\n            - expression: res.status\n              operator: eq\n              value: '200'\n        settings:\n          encodeUrl: true\n          timeout: 0\n          followRedirects: true\n          maxRedirects: 5\n          forwardAuthorizationHeader: true\n      - info:\n          name: Upload Evidence\n          type: http\n          seq: 4\n        http:\n          method: POST\n          url: '{{ baseUri }}/cases/me/evidence'\n          headers:\n            - name: Accept\n              value: application/json\n          body:\n            type: multipart-form\n            data:\n              - name: evidence[]\n                type: text\n                value: mock-evidence-text-content\n          auth:\n            type: bearer\n            token: '{{ caseToken }}'\n        runtime:\n          scripts:\n            - type: after-response\n              code: |-\n                if (res.status === 200 && res.body.data && res.body.data.evidence && res.body.data.evidence.length > 0) {\n                  bru.setVar(\"evidenceId\", res.body.data.evidence[res.body.data.evidence.length - 1].id);\n                }\n            - type: tests\n              code: |-\n                test(\"Status is 200 OK\", function() {\n                  expect(res.status).to.equal(200);\n                });\n                test(\"Returns case data with evidence array\", function() {\n                  expect(res.body.data.evidence).to.be.an('array');\n                });\n          assertions:\n            - expression: res.status\n              operator: eq\n              value: '200'\n        settings:\n          encodeUrl: true\n          timeout: 0\n          followRedirects: true\n          maxRedirects: 5\n          forwardAuthorizationHeader: true\n      - info:\n          name: Get Evidence Stream\n          type: http\n          seq: 5\n        http:\n          method: GET\n          url: '{{ baseUri }}/cases/me/evidence/{{ evidenceId }}'\n          headers:\n            - name: Accept\n              value: application/json\n          auth:\n            type: bearer\n            token: '{{ caseToken }}'\n        runtime:\n          scripts:\n            - type: tests\n              code: |-\n                test(\"Status is 200 OK\", function() {\n                  expect(res.status).to.equal(200);\n                });\n          assertions:\n            - expression: res.status\n              operator: eq\n              value: '200'\n        settings:\n          encodeUrl: true\n          timeout: 0\n          followRedirects: true\n          maxRedirects: 5\n          forwardAuthorizationHeader: true\n      - info:\n          name: Get Messages\n          type: http\n          seq: 6\n        http:\n          method: GET\n          url: '{{ baseUri }}/cases/me/messages'\n          headers:\n            - name: Accept\n              value: application/json\n          auth:\n            type: bearer\n            token: '{{ caseToken }}'\n        runtime:\n          scripts:\n            - type: tests\n              code: |-\n                test(\"Status is 200 OK\", function() {\n                  expect(res.status).to.equal(200);\n                });\n                test(\"Returns messages collection for Case Reporter\", function() {\n                  expect(res.body.messages).to.be.an('array');\n                });\n          assertions:\n            - expression: res.status\n              operator: eq\n              value: '200'\n        settings:\n          encodeUrl: true\n          timeout: 0\n          followRedirects: true\n          maxRedirects: 5\n          forwardAuthorizationHeader: true\n      - info:\n          name: Send Message\n          type: http\n          seq: 7\n        http:\n          method: POST\n          url: '{{ baseUri }}/cases/me/messages'\n          headers:\n            - name: Content-Type\n              value: application/json\n            - name: Accept\n              value: application/json\n          body:\n            type: json\n            data: |-\n              {\n                \"content\": \"I have uploaded supporting transaction receipts for this report.\"\n              }\n          auth:\n            type: bearer\n            token: '{{ caseToken }}'\n        runtime:\n          scripts:\n            - type: tests\n              code: |-\n                test(\"Status is 201 Created\", function() {\n                  expect(res.status).to.equal(201);\n                });\n                test(\"Message recorded with masked sender identity\", function() {\n                  expect(res.body.data.id).to.be.a('string');\n                  expect(res.body.data.senderType).to.equal('CASE_REPORTER');\n                });\n          assertions:\n            - expression: res.status\n              operator: eq\n              value: '201'\n        settings:\n          encodeUrl: true\n          timeout: 0\n          followRedirects: true\n          maxRedirects: 5\n          forwardAuthorizationHeader: true\n      - info:\n          name: Escalate Case\n          type: http\n          seq: 8\n        http:\n          method: POST\n          url: '{{ baseUri }}/cases/me/escalate'\n          headers:\n            - name: Accept\n              value: application/json\n          auth:\n            type: bearer\n            token: '{{ caseToken }}'\n        runtime:\n          scripts:\n            - type: tests\n              code: |-\n                test(\"Status is 200 OK\", function() {\n                  expect(res.status).to.equal(200);\n                });\n                test(\"Case escalation timestamp returned\", function() {\n                  expect(res.body.escalatedAt).to.be.a('string');\n                });\n          assertions:\n            - expression: res.status\n              operator: eq\n              value: '200'\n        settings:\n          encodeUrl: true\n          timeout: 0\n          followRedirects: true\n          maxRedirects: 5\n          forwardAuthorizationHeader: true\n  - info:\n      name: Department Head\n      type: folder\n      seq: 5\n    request:\n      auth: inherit\n    items:\n      - info:\n          name: Department Head Login\n          type: http\n          seq: 1\n        http:\n          method: POST\n          url: '{{ baseUri }}/auth/login'\n          headers:\n            - name: Content-Type\n              value: application/json\n            - name: Accept\n              value: application/json\n          body:\n            type: json\n            data: |-\n              {\n                \"email\": \"{{ deptHeadEmail }}\",\n                \"password\": \"{{ deptHeadPassword }}\"\n              }\n        runtime:\n          scripts:\n            - type: after-response\n              code: |-\n                if (res.status === 200 && res.body.token) {\n                  bru.setVar(\"deptHeadToken\", res.body.token);\n                  bru.setVar(\"staffToken\", res.body.token);\n                }\n            - type: tests\n              code: |-\n                test(\"Status is 200 OK\", function() {\n                  expect(res.status).to.equal(200);\n                });\n                test(\"Returns JWT token\", function() {\n                  expect(res.body.token).to.be.a('string');\n                });\n                test(\"User role is DEPARTMENT_HEAD\", function() {\n                  expect(res.body.user.role).to.equal('DEPARTMENT_HEAD');\n                });\n          assertions:\n            - expression: res.status\n              operator: eq\n              value: '200'\n        settings:\n          encodeUrl: true\n          timeout: 0\n          followRedirects: true\n          maxRedirects: 5\n          forwardAuthorizationHeader: true\n      - info:\n          name: Get Cases Queue\n          type: http\n          seq: 2\n        http:\n          method: GET\n          url: '{{ baseUri }}/cases'\n          headers:\n            - name: Accept\n              value: application/json\n          auth:\n            type: bearer\n            token: '{{ deptHeadToken }}'\n        runtime:\n          scripts:\n            - type: after-response\n              code: |-\n                if (res.status === 200 && res.body.data && res.body.data.length > 0) {\n                  bru.setVar(\"caseId\", res.body.data[0].id);\n                }\n            - type: tests\n              code: |-\n                test(\"Status is 200 OK\", function() {\n                  expect(res.status).to.equal(200);\n                });\n                test(\"Returns departmental intake queue\", function() {\n                  expect(res.body.data).to.be.an('array');\n                });\n          assertions:\n            - expression: res.status\n              operator: eq\n              value: '200'\n        settings:\n          encodeUrl: true\n          timeout: 0\n          followRedirects: true\n          maxRedirects: 5\n          forwardAuthorizationHeader: true\n      - info:\n          name: Get Case Detail\n          type: http\n          seq: 3\n        http:\n          method: GET\n          url: '{{ baseUri }}/cases/{{ caseId }}'\n          headers:\n            - name: Accept\n              value: application/json\n          auth:\n            type: bearer\n            token: '{{ deptHeadToken }}'\n        runtime:\n          scripts:\n            - type: after-response\n              code: |-\n                if (res.status === 200 && res.body.data && res.body.data.evidence && res.body.data.evidence.length > 0) {\n                  bru.setVar(\"evidenceId\", res.body.data.evidence[0].id);\n                }\n            - type: tests\n              code: |-\n                test(\"Status is 200 OK\", function() {\n                  expect(res.status).to.equal(200);\n                });\n                test(\"Returns complete case forensic details\", function() {\n                  expect(res.body.data.id).to.equal(bru.getVar('caseId'));\n                  expect(res.body.data.status).to.be.a('string');\n                });\n          assertions:\n            - expression: res.status\n              operator: eq\n              value: '200'\n        settings:\n          encodeUrl: true\n          timeout: 0\n          followRedirects: true\n          maxRedirects: 5\n          forwardAuthorizationHeader: true\n      - info:\n          name: Claim Case\n          type: http\n          seq: 4\n        http:\n          method: POST\n          url: '{{ baseUri }}/cases/{{ caseId }}/claim'\n          headers:\n            - name: Accept\n              value: application/json\n          auth:\n            type: bearer\n            token: '{{ deptHeadToken }}'\n        runtime:\n          scripts:\n            - type: tests\n              code: |-\n                test(\"Status is 200 OK\", function() {\n                  expect(res.status).to.equal(200);\n                });\n                test(\"Case assigned to department head\", function() {\n                  expect(res.body.data.id).to.equal(bru.getVar('caseId'));\n                });\n          assertions:\n            - expression: res.status\n              operator: eq\n              value: '200'\n        settings:\n          encodeUrl: true\n          timeout: 0\n          followRedirects: true\n          maxRedirects: 5\n          forwardAuthorizationHeader: true\n      - info:\n          name: Update Case Status\n          type: http\n          seq: 5\n        http:\n          method: PATCH\n          url: '{{ baseUri }}/cases/{{ caseId }}/status'\n          headers:\n            - name: Content-Type\n              value: application/json\n            - name: Accept\n              value: application/json\n          body:\n            type: json\n            data: |-\n              {\n                \"status\": \"INVESTIGATING\",\n                \"note\": \"Initial forensic evidence verified. Commencing internal audit review.\"\n              }\n          auth:\n            type: bearer\n            token: '{{ deptHeadToken }}'\n        runtime:\n          scripts:\n            - type: tests\n              code: |-\n                test(\"Status is 200 OK\", function() {\n                  expect(res.status).to.equal(200);\n                });\n                test(\"Status successfully updated\", function() {\n                  expect(res.body.data.status).to.equal('INVESTIGATING');\n                });\n          assertions:\n            - expression: res.status\n              operator: eq\n              value: '200'\n        settings:\n          encodeUrl: true\n          timeout: 0\n          followRedirects: true\n          maxRedirects: 5\n          forwardAuthorizationHeader: true\n      - info:\n          name: Get Case Evidence Stream\n          type: http\n          seq: 6\n        http:\n          method: GET\n          url: '{{ baseUri }}/cases/{{ caseId }}/evidence/{{ evidenceId }}'\n          headers:\n            - name: Accept\n              value: application/json\n          auth:\n            type: bearer\n            token: '{{ deptHeadToken }}'\n        runtime:\n          scripts:\n            - type: tests\n              code: |-\n                test(\"Status is 200 OK\", function() {\n                  expect(res.status).to.equal(200);\n                });\n          assertions:\n            - expression: res.status\n              operator: eq\n              value: '200'\n        settings:\n          encodeUrl: true\n          timeout: 0\n          followRedirects: true\n          maxRedirects: 5\n          forwardAuthorizationHeader: true\n      - info:\n          name: Get Case Messages\n          type: http\n          seq: 7\n        http:\n          method: GET\n          url: '{{ baseUri }}/cases/{{ caseId }}/messages'\n          headers:\n            - name: Accept\n              value: application/json\n          auth:\n            type: bearer\n            token: '{{ deptHeadToken }}'\n        runtime:\n          scripts:\n            - type: tests\n              code: |-\n                test(\"Status is 200 OK\", function() {\n                  expect(res.status).to.equal(200);\n                });\n                test(\"Returns messages collection for case\", function() {\n                  expect(res.body.messages).to.be.an('array');\n                });\n          assertions:\n            - expression: res.status\n              operator: eq\n              value: '200'\n        settings:\n          encodeUrl: true\n          timeout: 0\n          followRedirects: true\n          maxRedirects: 5\n          forwardAuthorizationHeader: true\n      - info:\n          name: Send Case Message\n          type: http\n          seq: 8\n        http:\n          method: POST\n          url: '{{ baseUri }}/cases/{{ caseId }}/messages'\n          headers:\n            - name: Content-Type\n              value: application/json\n            - name: Accept\n              value: application/json\n          body:\n            type: json\n            data: |-\n              {\n                \"content\": \"Thank you for providing the documentation. The investigation is underway.\"\n              }\n          auth:\n            type: bearer\n            token: '{{ deptHeadToken }}'\n        runtime:\n          scripts:\n            - type: tests\n              code: |-\n                test(\"Status is 201 Created\", function() {\n                  expect(res.status).to.equal(201);\n                });\n                test(\"Message recorded from department head\", function() {\n                  expect(res.body.data.senderType).to.equal('DEPARTMENT_HEAD');\n                });\n          assertions:\n            - expression: res.status\n              operator: eq\n              value: '201'\n        settings:\n          encodeUrl: true\n          timeout: 0\n          followRedirects: true\n          maxRedirects: 5\n          forwardAuthorizationHeader: true\n      - info:\n          name: Get Case Audit Logs\n          type: http\n          seq: 9\n        http:\n          method: GET\n          url: '{{ baseUri }}/cases/{{ caseId }}/audit-logs'\n          headers:\n            - name: Accept\n              value: application/json\n          auth:\n            type: bearer\n            token: '{{ deptHeadToken }}'\n        runtime:\n          scripts:\n            - type: tests\n              code: |-\n                test(\"Status is 200 OK\", function() {\n                  expect(res.status).to.equal(200);\n                });\n                test(\"Returns chronological audit trail for case\", function() {\n                  expect(res.body.data).to.be.an('array');\n                });\n          assertions:\n            - expression: res.status\n              operator: eq\n              value: '200'\n        settings:\n          encodeUrl: true\n          timeout: 0\n          followRedirects: true\n          maxRedirects: 5\n          forwardAuthorizationHeader: true\n  - info:\n      name: Real Time Auth\n      type: folder\n      seq: 6\n    request:\n      auth: inherit\n    items:\n      - info:\n          name: Broadcast Auth (Staff)\n          type: http\n          seq: 1\n        http:\n          method: POST\n          url: '{{ apiOrigin }}/broadcasting/auth'\n          headers:\n            - name: Content-Type\n              value: application/json\n            - name: Accept\n              value: application/json\n          body:\n            type: json\n            data: |-\n              {\n                \"socket_id\": \"{{ socketId }}\",\n                \"channel_name\": \"private-case.{{ caseId }}\"\n              }\n          auth:\n            type: bearer\n            token: '{{ staffToken }}'\n        runtime:\n          scripts:\n            - type: after-response\n              code: |-\n                if (res.status === 200 && res.body.auth) {\n                  bru.setVar(\"broadcastAuthSignature\", res.body.auth);\n                }\n            - type: tests\n              code: |-\n                test(\"Status is 200 OK\", function() {\n                  expect(res.status).to.equal(200);\n                });\n                test(\"Returns Pusher HMAC auth signature\", function() {\n                  expect(res.body.auth).to.be.a('string');\n                  expect(res.body.auth).to.include(':');\n                });\n          assertions:\n            - expression: res.status\n              operator: eq\n              value: '200'\n        settings:\n          encodeUrl: true\n          timeout: 0\n          followRedirects: true\n          maxRedirects: 5\n          forwardAuthorizationHeader: true\n      - info:\n          name: Broadcast Auth (Reporter)\n          type: http\n          seq: 2\n        http:\n          method: POST\n          url: '{{ apiOrigin }}/broadcasting/auth'\n          headers:\n            - name: Content-Type\n              value: application/json\n            - name: Accept\n              value: application/json\n          body:\n            type: json\n            data: |-\n              {\n                \"socket_id\": \"{{ socketId }}\",\n                \"channel_name\": \"private-case.{{ caseId }}\"\n              }\n          auth:\n            type: bearer\n            token: '{{ caseToken }}'\n        runtime:\n          scripts:\n            - type: after-response\n              code: |-\n                if (res.status === 200 && res.body.auth) {\n                  bru.setVar(\"broadcastAuthSignature\", res.body.auth);\n                }\n            - type: tests\n              code: |-\n                test(\"Status is 200 OK\", function() {\n                  expect(res.status).to.equal(200);\n                });\n                test(\"Returns Pusher HMAC auth signature for anonymous channel\", function() {\n                  expect(res.body.auth).to.be.a('string');\n                });\n          assertions:\n            - expression: res.status\n              operator: eq\n              value: '200'\n        settings:\n          encodeUrl: true\n          timeout: 0\n          followRedirects: true\n          maxRedirects: 5\n          forwardAuthorizationHeader: true\n      - info:\n          name: Chat Connection\n          type: websocket\n          seq: 3\n        websocket:\n          url: ws://{{ wsHost }}:{{ wsPort }}/app/{{ reverbAppKey }}?protocol=7&client=js&version=8.4.0-reverb&flash=false\n          headers:\n            - name: Accept\n              value: application/json\n          message:\n            - title: Pusher Ping Heartbeat\n              message:\n                type: json\n                data: |-\n                  {\n                    \"event\": \"pusher:ping\",\n                    \"data\": {}\n                  }\n            - title: Subscribe to Private Case Channel\n              message:\n                type: json\n                data: |-\n                  {\n                    \"event\": \"pusher:subscribe\",\n                    \"data\": {\n                      \"auth\": \"{{ broadcastAuthSignature }}\",\n                      \"channel\": \"private-case.{{ caseId }}\"\n                    }\n                  }\n            - title: Subscribe to Department Presence Channel\n              message:\n                type: json\n                data: |-\n                  {\n                    \"event\": \"pusher:subscribe\",\n                    \"data\": {\n                      \"auth\": \"{{ broadcastAuthSignature }}\",\n                      \"channel\": \"presence-department\"\n                    }\n                  }\n            - title: Send Client Typing Indicator\n              message:\n                type: json\n                data: |-\n                  {\n                    \"event\": \"client-typing\",\n                    \"channel\": \"private-case.{{ caseId }}\",\n                    \"data\": {\n                      \"typing\": true\n                    }\n                  }\n          auth: inherit\n        docs: |-\n          ### Laravel Reverb Real-Time WebSocket Connection\n\n          Connects to the Laravel Reverb WebSocket server running Pusher Protocol v7.\n\n          #### Workflow:\n          1. Authenticate with **Broadcast Auth (Staff)** or **Broadcast Auth (Reporter)** to obtain the `broadcastAuthSignature`.\n          2. Click **Connect** in Bruno to establish the WebSocket handshake.\n          3. Send the **Subscribe to Private Case Channel** message to join `private-case.{{ caseId }}`.\n          4. Real-time `MessageSent` and presence status events will stream live into Bruno.\ndocs:\n  content: |\n    # Verita API - Bruno v4 OpenCollection Test Suite & Repository\n\n    Welcome to the official **Verita API** executable test collection and development repository. This repository contains the complete **Bruno v4 (OpenCollection YAML)** test suite covering every REST endpoint, authentication flow, role permission boundary, audit ledger, and Laravel Reverb WebSocket channel.\n\n    ---\n\n    ## 1. System Identity & Authorship\n\n    - **System**: Verita Case Reporting & Case Management System\n    - **Standards Compliance**: ISO 37002:2021 Case Reporting Management Systems, EU Directive 2019/1937\n    - **Lead Architect & Engineer**: [Carmine Akanabe](https://github.com/CarmineAkanabe)\n    - **Specification**: [OpenCollection v1.0.0](https://spec.opencollection.com) (YAML-native)\n    - **API Runtime**: Laravel 11/13 REST API with Laravel Reverb WebSockets\n\n    ---\n\n    ## 2. Repository Layout\n\n    ```\n    Verita-API/\n    \u251C\u2500\u2500 .gitignore                          # Clean VCS ignores\n    \u251C\u2500\u2500 opencollection.yml                  # Root OpenCollection manifest\n    \u251C\u2500\u2500 package.json                        # CLI test automation scripts\n    \u251C\u2500\u2500 README.md                           # System and test manual\n    \u251C\u2500\u2500 environments/\n    \u2502   \u2514\u2500\u2500 Local.yml                       # Pre-configured Local environment variables\n    \u251C\u2500\u2500 Health/                             # System liveness & ping\n    \u2502   \u251C\u2500\u2500 folder.yml\n    \u2502   \u2514\u2500\u2500 Ping.yml\n    \u251C\u2500\u2500 Account & Notifications/            # Staff profile & notifications\n    \u2502   \u251C\u2500\u2500 folder.yml\n    \u2502   \u251C\u2500\u2500 Staff Dashboard.yml\n    \u2502   \u251C\u2500\u2500 Update Profile.yml\n    \u2502   \u251C\u2500\u2500 Notifications.yml\n    \u2502   \u251C\u2500\u2500 Mark Notification Read.yml\n    \u2502   \u2514\u2500\u2500 Logout.yml\n    \u251C\u2500\u2500 Manager/                            # Org-wide administration\n    \u2502   \u251C\u2500\u2500 folder.yml\n    \u2502   \u251C\u2500\u2500 Auth.yml                        # Manager JWT login\n    \u2502   \u251C\u2500\u2500 Get Departments.yml\n    \u2502   \u251C\u2500\u2500 Create Department.yml\n    \u2502   \u251C\u2500\u2500 Update a Department.yml\n    \u2502   \u251C\u2500\u2500 Department Heads.yml\n    \u2502   \u251C\u2500\u2500 Create Dept Head.yml\n    \u2502   \u251C\u2500\u2500 Update Dept Head.yml\n    \u2502   \u251C\u2500\u2500 Get Assign Case.yml\n    \u2502   \u251C\u2500\u2500 Assign Case.yml\n    \u2502   \u251C\u2500\u2500 Get Report.yml                  # Executive analytics\n    \u2502   \u251C\u2500\u2500 All Audit Logs.yml              # System-wide audit ledger\n    \u2502   \u251C\u2500\u2500 Delete Dept Head.yml\n    \u2502   \u2514\u2500\u2500 Delete Department.yml\n    \u251C\u2500\u2500 Reporter/                           # Anonymous zero-PII Case Reporter\n    \u2502   \u251C\u2500\u2500 folder.yml\n    \u2502   \u251C\u2500\u2500 Submit Case.yml                 # Generates caseId + 6-char PIN\n    \u2502   \u251C\u2500\u2500 Verify PIN.yml                  # Obtains Case Reporter JWT (auth:case-api)\n    \u2502   \u251C\u2500\u2500 Case Dashboard.yml              # Anonymized case state\n    \u2502   \u251C\u2500\u2500 Upload Evidence.yml\n    \u2502   \u251C\u2500\u2500 Evidence.yml\n    \u2502   \u251C\u2500\u2500 Messages.yml\n    \u2502   \u251C\u2500\u2500 Send Message.yml\n    \u2502   \u2514\u2500\u2500 Escalate Case.yml\n    \u251C\u2500\u2500 Department Head/                    # Departmental investigation\n    \u2502   \u251C\u2500\u2500 folder.yml\n    \u2502   \u251C\u2500\u2500 Auth.yml                        # Department Head JWT login\n    \u2502   \u251C\u2500\u2500 Cases Queue.yml\n    \u2502   \u251C\u2500\u2500 Case Dashboard.yml              # Forensic detail + Gemini AI triage\n    \u2502   \u251C\u2500\u2500 Claim Case.yml\n    \u2502   \u251C\u2500\u2500 Update Case Status.yml\n    \u2502   \u251C\u2500\u2500 Case Evidence.yml\n    \u2502   \u251C\u2500\u2500 Case Messages.yml\n    \u2502   \u251C\u2500\u2500 Send Case Message.yml\n    \u2502   \u2514\u2500\u2500 Case Audit Logs.yml             # Chronological case timeline\n    \u2514\u2500\u2500 Real Time Auth/                     # Reverb WebSockets & broadcasting\n        \u251C\u2500\u2500 folder.yml\n        \u251C\u2500\u2500 Broadcast Auth - Staff.yml      # Pusher private channel auth\n        \u251C\u2500\u2500 Broadcast Auth - Reporter.yml   # Anonymous Case Reporter channel auth\n        \u2514\u2500\u2500 Chat Connection.yml             # Live WebSocket connection\n    ```\n\n    ---\n\n    ## 3. Quickstart Guide\n\n    ### Option A: Using Bruno GUI (v4+)\n    1. Open the **Bruno** desktop application.\n    2. Click **Open Collection**.\n    3. Select this folder (`C:\\Users\\CARMINE\\Documents\\bruno\\Verita-API`).\n    4. Select the **Local** environment from the top-right dropdown.\n    5. Execute requests sequentially or run entire folders using the **Runner**.\n\n    ### Option B: Using Bruno CLI\n    Run all automated tests against your local backend with a single command:\n\n    ```bash\n    # Run entire test suite\n    npm test\n\n    # Or run specific test domains\n    npm run test:health\n    npm run test:manager\n    npm run test:depthead\n    npm run test:reporter\n    npm run test:realtime\n    ```\n\n    ---\n\n    ## 4. Default Testing Credentials & Services\n\n    | Role                | Email                 | Password   | Scope                                      |\n    | ------------------- | --------------------- | ---------- | ------------------------------------------ |\n    | **Manager**         | `manager@verita.com`  | `password` | Full organization oversight & audit ledger |\n    | **Department Head** | `depthead@verita.com` | `password` | Departmental intake queue & investigation  |\n    | **Case Reporter**   | *Anonymous*           | 6-char PIN | Zero-PII token generated per submission    |\n\n    ### Local Ports\n    - **Laravel REST API**: `http://localhost:8000/api/v1` (`php artisan serve --port=8000`)\n    - **Laravel Reverb WS**: `ws://localhost:8080` (`php artisan reverb:start --port=8080`)\n    - **Vue 3 Frontend**: `http://localhost:5173` (`npm run dev`)\n\n    ---\n\n    ## 5. Automated Dynamic Chaining\n\n    This collection includes automated **After-Response Scripts** and **Before-Request Hooks** so you do not need to manually copy and paste tokens:\n\n    1. **Manager / Dept Head Login**: Automatically extracts and sets `managerToken`, `deptHeadToken`, and active `staffToken`.\n    2. **Submit Case**: Dynamically generates an `Idempotency-Key` UUID, submits the report, and captures `caseId` and `trackingPin`.\n    3. **Verify PIN**: Authenticates with `trackingPin` and stores the anonymous `caseToken`.\n    4. **Broadcast Auth**: Obtains the Pusher HMAC signature and injects it into `broadcastAuthSignature` for instant WebSocket channel subscription.\n    5. **Entity Chaining**: Automatically captures created `departmentId`, `departmentHeadId`, `notificationId`, and `evidenceId` for downstream requests.\n\n    ---\n\n    ## 6. Real-Time WebSocket Testing\n\n    The collection includes a configured WebSocket request at `Real Time Auth/Chat Connection.yml`:\n\n    1. **Protocol**: Pusher Protocol v7 over Laravel Reverb.\n    2. **URL**: `ws://{{ wsHost }}:{{ wsPort }}/app/{{ reverbAppKey }}?protocol=7&client=js&version=8.4.0-reverb&flash=false`\n    3. **Pre-Configured Messages**:\n       - **Pusher Ping Heartbeat**: Tests connection liveness (`pusher:ping`).\n       - **Subscribe to Private Case Channel**: Subscribes to `private-case.{{ caseId }}` using the HMAC signature obtained from Broadcast Auth.\n       - **Subscribe to Presence Channel**: Tests departmental presence broadcast (`presence-department`).\n       - **Client Typing Indicator**: Emits a client-level whisper event.\n\n    ---\n\n    ## 7. Compliance & Privacy Rules\n\n    - **Zero-PII Anonymous Intake**: Anonymous reporters are never registered with email or personal data. All identity is air-gapped behind cryptographically hashed PINs.\n    - **Asymmetric Identity**: In two-way communication channels, the Case Reporter is strictly displayed as `Case<ID>Reporter`.\n    - **Immutable Audit Trails**: Every status modification, claim, message, and evidence review writes an immutable record to `AuditLogService`.\n\n    ---\n\n    ## 8. Author & Maintainer\n\n    Designed and architected by **[Carmine Akanabe](https://github.com/CarmineAkanabe)** for the **Verita Case Reporter System**.\n  type: text/markdown\nbundled: true\nextensions:\n  bruno:\n    ignore:\n      - node_modules\n      - .git\n    exportedAt: '2026-09-23T06:03:46.571Z'\n    exportedUsing: Bruno/4.1.0\n";
            new window.OpenCollection({
                target: document.getElementById('opencollection-container'),
                opencollection: collectionData,
                theme: 'light'
            });
        </script>
    @endverbatim
